static void Require(bool condition, const std::string& message) {
	if (!condition) {
		throw std::runtime_error(message);
	}
}

static sgre::resource::MotionPoint Point(const std::array<std::uint32_t, 2>& words) {
	return {std::bit_cast<float>(words[0]), std::bit_cast<float>(words[1])};
}

static float Compare(const sgre::resource::MotionBezierLattice& actual, const std::vector<std::uint32_t>& expected, const std::string& phase) {
	Require(actual.Controls.size() * 2 == expected.size(), "native fix fixture count differs");
	float maximum = 0;
	for (std::size_t index = 0; index != actual.Controls.size(); ++index) {
		const std::array<float, 2> point{actual.Controls[index].X, actual.Controls[index].Y};
		for (std::size_t axis = 0; axis != point.size(); ++axis) {
			const float value = std::bit_cast<float>(expected[index * 2 + axis]);
			const float error = std::abs(point[axis] - value) / std::max(1.0f, std::abs(value));
			Require(std::isfinite(point[axis]) && error <= 0.000008f, phase + " native fix differs at point " + std::to_string(index) + ": actual=" + std::to_string(point[axis]) + ", expected=" + std::to_string(value));
			maximum = std::max(maximum, error);
		}
	}
	return maximum;
}

static float Check(std::uint8_t degree, std::initializer_list<std::array<std::uint32_t, 2>> fix_words, const std::array<std::uint32_t, 6>& posture_words, const std::array<std::uint32_t, 6>& inverse_words, std::initializer_list<std::array<std::uint32_t, 2>> controls, const std::vector<std::uint32_t>& normalized, std::initializer_list<std::array<std::uint32_t, 2>> target_words, const std::vector<std::uint32_t>& corrected) {
	std::vector<sgre::resource::MotionPoint> fixes;
	std::vector<sgre::resource::MotionPoint> targets;
	for (const auto& words : fix_words) {
		fixes.push_back(Point(words));
	}
	for (const auto& words : target_words) {
		targets.push_back(Point(words));
	}
	sgre::scene::EmotePhysicalPosture posture;
	for (std::size_t axis = 0; axis != 3; ++axis) {
		posture.Coordinate[axis] = std::bit_cast<float>(posture_words[axis]);
	}
	posture.Rotation = std::bit_cast<float>(posture_words[3]);
	posture.Cosine = std::bit_cast<float>(posture_words[4]);
	posture.Sine = std::bit_cast<float>(posture_words[5]);
	sgre::resource::MotionMeshMatrix inverse;
	inverse.XX = std::bit_cast<float>(inverse_words[0]);
	inverse.XY = std::bit_cast<float>(inverse_words[1]);
	inverse.TranslationX = std::bit_cast<float>(inverse_words[2]);
	inverse.YX = std::bit_cast<float>(inverse_words[3]);
	inverse.YY = std::bit_cast<float>(inverse_words[4]);
	inverse.TranslationY = std::bit_cast<float>(inverse_words[5]);
	sgre::resource::MotionBezierLattice lattice;
	lattice.EncodedDegree = degree;
	for (const auto& words : controls) {
		lattice.Controls.push_back(Point(words));
	}
	sgre::scene::EmoteMeshFixAlignment alignment(fixes, 1.25f, 2.5f);
	alignment.Normalize(lattice, posture, inverse);
	const auto normalization_error = Compare(lattice, normalized, "normalization");
	alignment.Correct(lattice, targets, inverse);
	return std::max(normalization_error, Compare(lattice, corrected, "correction"));
}

